 if(total>500||ids.length>10||(!total&&ids.length)||(total>0&&page<=Math.ceil(total/10)&&ids.length!==Math.min(10,total-(page-1)*10)))throw new Error('Die Herstellerliste ist unvollständig oder ihr Format wurde geändert.');
